/* rows1.c -- 使用嵌套循环 */
#include <stdio.h>
#define ROWS 6
#define CHARS 10
int main(void)
{
int row;
char ch;
for (row = 0; row < ROWS; row++)          /* 第10行 */
{
for (ch = 'A'; ch < ('A' + CHARS); ch++)     /* 第12行 */
printf("%c", ch);
printf("\n");
}

// rows2.c -- 依赖外部循环的嵌套循环
#include <stdio.h>

int main(void)
{
const int ROWS = 6;
const int CHARS = 6;
int row;
char ch;
for (row = 0; row < ROWS; row++)
{
for (ch = ('A' + row); ch < ('A' + CHARS); ch++)
printf("%c", ch);
printf("\n");
}
return 0;
}

